const WhatsappButton = ({ callBackScreen, whatsappNumberCore, defaultMessageLogin, buttonText = 'Sign Up with WhatsApp', buttonStyle, buttonTextStyle, iconStyle, iconColor, iconSize, }) => {
    const number = whatsappNumberCore || process.env.WHATSAPP_NUMBER_CORE || process.env.EXPO_PUBLIC_WHATSAPP_NUMBER_CORE;
    const message = defaultMessageLogin || process.env.DEFAULT_MESSAGE_LOGIN || process.env.EXPO_PUBLIC_DEFAULT_MESSAGE_LOGIN;
    const handlePress = () => {
        if (!number || !message) {
            Alert.alert('Error', 'Number or message not configured.');
            console.error('Number or message not configured.');
            return;
        }
        const sanitizedNumber = number.replace(/\D/g, '');
        const url = `https://wa.me/${sanitizedNumber}?text=${encodeURIComponent(message)}`;
        Linking.canOpenURL(url)
            .then((supported) => {
            if (!supported) {
                Alert.alert('Erro', 'WhatsApp is not installed.');
            }
            else {
                Linking.openURL(url)
                    .then(() => {
                    callBackScreen();
                })
                    .catch(() => {
                    Alert.alert('Error', 'Unable to open WhatsApp.');
                });
            }
        })
            .catch(() => console.log('An error occurred while checking WhatsApp.'));
    };
    return (<Pressable style={[styles.button, buttonStyle]} onPress={handlePress}>
      <WhatsappIcon width={iconSize} height={iconSize} color={iconColor} style={iconStyle}/>
      <Text style={[styles.buttonText, buttonTextStyle]}>{buttonText}</Text>
    </Pressable>);
};
export { WhatsappButton };

